
/* AOG GRACE COMPASS — provisional ES overlay, batch 2 (remaining 62 rows).
   English crosswalk remains the single source of truth. Review pending. */
window.AOG_CROSSWALK_ES = window.AOG_CROSSWALK_ES || {};
Object.assign(window.AOG_CROSSWALK_ES, {
  'K-2|U1·L3 — Everyone Makes Mistakes': {lesson:'U1·L3 — Todos cometen errores',theme:'Identidad · Tolerancia al error',scene:'Cap. 3 · Todos cometen errores. La clase aprende que los errores son parte de ser persona — los adultos los cometen, los maestros los cometen, Sammy los comete.',chart:'TODOS NOS EQUIVOCAMOS (K-2) — dibujos de adultos, niños, incluso Sammy, todos con globitos de «ups».',neuro:'Regla de tarjeta de pupitre: «Un error = algo que hice. Un error NO es quién soy. Igual que: derramar el jugo no significa que yo sea jugo». La lógica literal cala.'},
  'K-2|U1·L4 — Inner Critic vs. Inner Coach (K-2)': {lesson:'U1·L4 — Crítico interior vs. Entrenador interior (K-2)',theme:'Autocompasión · Voz interior',scene:'Cap. 4 · Mi voz interior — ¿amable o cruel? Sammy presenta al Entrenador Amable y al Gruñón — las dos voces que viven adentro.',chart:'ENTRENADOR AMABLE vs. GRUÑÓN (K-2) — dos caritas de caricatura. Entrenador Amable: «Puedes intentarlo de nuevo». Gruñón: «Siempre lo arruinas».',neuro:'Externalice las dos voces como personajes concretos. Practiquen el guion del Entrenador Amable en voz alta, al unísono. No exija que el niño detecte cuál voz es interna — dé el guion; ellos lo recitan.'},
  'K-2|U1·L5 — Guilt vs. Shame (Oops vs. I Am Bad)': {lesson:'U1·L5 — Culpa vs. Vergüenza (Ups vs. Soy Malo)',theme:'Autocompasión · Culpa vs. Vergüenza',scene:'Cap. 5 · Ups vs. Soy Malo. Kenji (de otro salón) dice «Soy una persona TERRIBLE». Marcus escribe la primera tarjeta en el Muro de los Errores: «Tiré la torre de bloques de un amigo. Pedí perdón. La reconstruimos. Ahora camino más despacio cerca de los bloques».',chart:'UPS vs. SOY MALO (K-2) — dos tarjetas: UPS = lo que HICE (se arregla). SOY MALO = quién SOY (falso). El Muro de los Errores comienza aquí.',neuro:'Marco de frase en una tarjeta de pupitre: «Hice ___. Eso es el UPS. No soy malo. Soy el mismo niño». Tres espacios, mismo orden. Practiquen primero con ejemplos de bajo riesgo.'},
  'K-2|U1·L6 — I Am More Than My Worst Moment (K-2)': {lesson:'U1·L6 — Soy más que mi peor momento (K-2)',theme:'Identidad · Crecimiento',scene:'Cap. 6 · Puedo cambiar y crecer. El salón planta semillas y las observa brotar. Sammy: «Tú estás creciendo de la misma forma. Un poquito cada día. No lo puedes ver. Pero está pasando».',chart:'ESTOY CRECIENDO (K-2) — un diagrama semilla → brote → planta con el nombre del niño al lado.',neuro:'Use una tabla de crecimiento literal en la pared; marque la estatura del niño cada mes. «Estás creciendo en tu cuerpo. Lo mismo es cierto por dentro». El recurso visual literal ancla lo abstracto.'},
  'K-2|U2·L2 — The Weight We Carry (K-2)': {lesson:'U2·L2 — El peso que cargamos (K-2)',theme:'Autocompasión · La mochila pesada',scene:'Cap. 9 · Cargar demasiado. La Sra. Calloway se pone la mochila azul de correa rota y va dejando caer piedra tras piedra hasta quedar encorvada. «Algunas piedras entran por un ratito. Pero cada piedra tiene que salir en algún momento». Cada niño recibe una piedrita gris azulada para su pupitre.',chart:'MI MOCHILA (K-2) — una mochila dibujada con piedras etiquetadas preocupación, perdón, tristeza.',neuro:'USE LA MOCHILA LITERAL. Deje que el niño sostenga las piedras reales. El tacto = la comprensión. Arme una bandeja para clasificar: GUARDAR / SOLTAR / NO ES MÍA. La traducción concreta más profunda del año K-2.'},
  'K-2|U2·L4 — Kind Coach Practice': {lesson:'U2·L4 — Práctica del Entrenador Amable',theme:'Autocompasión · Prueba del amigo',scene:'Cap. 11 · Ser amable conmigo. La clase practica decirse a sí mismos las cosas amables que le dirían a un amigo. Sammy: «¿Le dirías eso a un amigo? Si no, no te lo digas a ti mismo».',chart:'HÁBLATE COMO A UN AMIGO (K-2) — un niño y su reflejo en el espejo, ambos con globos de palabras amables.',neuro:'Tarjetas de autocharla amable prescritas: «Está bien equivocarse». «Sigues siendo bueno». «Puedes intentarlo de nuevo». El niño las lee en voz alta en un rincón tranquilo. La autocharla con guion siempre supera a la improvisada.'},
  'K-2|U2·L5 — The Letting-Go Practice': {lesson:'U2·L5 — La práctica de soltar',theme:'Autocompasión · Soltar',scene:'Cap. 12 · Soltar — la práctica. Al final del día, cada niño toma la piedra de su pupitre y la coloca en una canasta junto a la puerta. La Sra. Calloway: «Suelta la piedra de una cosa que estés listo para dejar de cargar».',chart:'SOLTANDO PIEDRAS (K-2) — una mano que se abre sobre una canasta y suelta una piedra. «Es mía para soltarla».',neuro:'La acción literal ES la lección: sostener la piedra, caminar a la canasta, abrir la mano, oír el clic. Esta secuencia es toda la enseñanza. No exija que el niño verbalice lo que suelta.'},
  'K-2|U2·L6 — When Self-Forgiveness Is Hard': {lesson:'U2·L6 — Cuando perdonarse es difícil',theme:'Autocompasión · El perdón más difícil',scene:'Cap. 13 · Cuando es difícil perdonarte. Marcus menciona algo que no le ha contado a nadie — algo que le dijo a Aaliyah, su hermana de tres años. No puede soltar la piedra.',chart:'ALGUNAS PIEDRAS SON PESADAS (K-2) — un niño sentado junto a una piedra, Sammy a su lado. «No la sueltas hoy. Te sientas con ella. Mañana lo intentas de nuevo».',neuro:'Honre un NO. Si el niño no está listo, no lo empuje. Ofrezca una «caja para guardar» con tapa: «Sigue aquí. Pero ya no la cargas sobre los hombros». La contención como compasión.'},
  'K-2|U3·L1 — Your Hurt Is Real': {lesson:'U3·L1 — Tu dolor es real',theme:'Perdón · Validar el dolor',scene:'Cap. 15 · Tu dolor es real. Mia, herida por algo que dijo su primo, aprende que los dolores son reales aun cuando los adultos digan «no fue para tanto».',chart:'TU DOLOR ES REAL (K-2) — una pequeña curita sobre un corazón. «Los moretones que se ven y los que no se ven — ambos son reales».',neuro:'Valide aun cuando el dolor parezca desproporcionado. «No eres demasiado sensible. Eres sensible. Así es tu sistema nervioso. El dolor es real». Nunca minimice los dolores de origen sensorial.'},
  'K-2|U3·L3 — Forgiveness vs. Reconciliation (K-2)': {lesson:'U3·L3 — Perdón vs. Reconciliación (K-2)',theme:'Perdón · vs. Reconciliación',scene:'Cap. 17 · Perdonar no es lo mismo que confiar. Sammy explica: puedes perdonar a alguien en tu corazón y aun así no ser mejores amigos enseguida. Perdonar es para ti. Confiar es entre dos personas.',chart:'PERDONAR vs. SER AMIGOS DE NUEVO (K-2) — dos círculos separados. Uno: «Ya no lo estoy cargando». El otro: «Volvemos a jugar juntos».',neuro:'CRÍTICO para estudiantes autistas vulnerables a ofensas repetidas de acoso. «Perdonar = suelto la piedra. Confiar = la otra persona se lo gana de vuelta, despacio, actuando de forma segura». La confianza es un patrón, no una decisión.'},
  'K-2|U3·L5 — Narrative Identity (K-2)': {lesson:'U3·L5 — Identidad narrativa (K-2)',theme:'Perdón · Identidad narrativa',scene:'Cap. 19 · Mi historia no es todo lo que soy. Maya, cuya historia incluye vivir con su abuela en vez de con su mamá, aprende que su historia difícil es parte de ella — pero no todo lo que es.',chart:'SOY MÁS QUE MI HISTORIA (K-2) — un niño dentro de un círculo, una pequeña burbuja-historia a su lado, no encima. «La historia es parte de mí. No es todo lo que soy».',neuro:'Para un niño cuya diferencia es el centro de las conversaciones de los adultos: «El autismo es parte de cómo eres. No es todo lo que eres. También eres chistoso. También construyes cosas. También eres amable». Nombre las otras partes de forma concreta.'},
  'K-2|U4·L1 — What Is Grace? (K-2)': {lesson:'U4·L1 — ¿Qué es la gracia? (K-2)',theme:'Gracia · Definición',scene:'Cap. 22 · ¿Cómo se ve la gracia? Sammy: «La gracia es cuando le das a alguien algo que no se ganó. Una segunda oportunidad. Una palabra amable cuando fue cruel. Un abrazo cuando te empujó». La clase hace una Lista de Gracia.',chart:'LA GRACIA ES UN REGALO (K-2) — una cajita de regalo que se entrega, con quien la da sonriendo. «Gracia = dar algo bueno cuando no se ganó».',neuro:'SOLO ejemplos concretos. No «generosidad de espíritu». En su lugar: «La gracia es dejar que tu hermana juegue con tu camión favorito aunque haya roto el otro». Tres ejemplos observables superan a una abstracción.'},
  'K-2|U4·L3 — The Pause (K-2)': {lesson:'U4·L3 — La pausa (K-2)',theme:'Gracia · Interpretación caritativa',scene:'Cap. 23 · Dar el beneficio de la duda. Theo se da cuenta de que cuando Jordan no le devuelve el saludo, quizá no signifique que Jordan está enojado. Tal vez no escuchó. Tal vez tuvo una mala mañana.',chart:'QUIZÁ-QUIZÁ-QUIZÁ (K-2) — tres globos de pensamiento, cada uno empieza con «quizá…». «Antes de decidir que mi amigo es malo, pienso en tres quizás».',neuro:'DIFÍCIL para estudiantes que interpretan las señales de forma literal. Protocolo: «Si un amigo hace X, haz una pausa y piensa en tres razones por las que tal vez NO sea sobre mí, antes de decidir que lo es. Hambre. Cansancio. No me vio. Luego pregunto». Hazlo un guion, no una corazonada.'},
  'K-2|U4·L5 — Difficult vs. Unsafe (K-2)': {lesson:'U4·L5 — Difícil vs. Inseguro (K-2)',theme:'Gracia · con límites',scene:'Cap. 25 · Gracia con personas difíciles. Kezia habla de un primo que es cruel. La Sra. Calloway: «La gracia puede ser callada. La gracia puede ser un pensamiento amable aunque te quedes lejos».',chart:'LA GRACIA NO ES SER UN TAPETE (K-2) — un niño sonriente con una línea de límite clara a su alrededor. «Soy amable. Y tampoco soy para que me pisoteen».',neuro:'Enseñanza de seguridad para estudiantes con mayor riesgo de ser aprovechados. «Si alguien es inseguro — golpea, rompe cosas, me asusta — NO tengo que estar cerca para dar gracia. Puedo dar gracia alejándome y sin responder con cosas crueles». La distancia es una forma válida de gracia.'},
  '3-5|U1·L4 — Inner Critic vs. Inner Coach': {lesson:'U1·L4 — Crítico interior vs. Entrenador interior',theme:'Autocompasión · El Crítico nombrado',scene:'Cap. 4 · Mi crítico interior vs. mi entrenador interior. Priya llena la columna del Crítico en tres minutos y se queda totalmente atascada en la del Entrenador. Voltea la hoja y escribe «QUERIDA PRIYA, si Hannah dijera estas cosas, yo le diría —».',chart:'CRÍTICO INTERIOR vs. ENTRENADOR INTERIOR (3-5) — dos columnas de frases emparejadas («Eres malo en esto» ↔ «Todavía estás aprendiendo»). Cinco filas emparejadas.',neuro:'Provea de antemano los guiones del Entrenador interior — generar lenguaje autocompasivo sobre la marcha es la petición equivocada para muchos cerebros autistas. «Lee en voz alta estas tres frases del Entrenador cuando el Crítico se ponga ruidoso». La internalización llega después, con la repetición.'},
  '3-5|U1·L5 — Guilt vs. Shame': {lesson:'U1·L5 — Culpa vs. Vergüenza',theme:'Autocompasión · Culpa vs. Vergüenza',scene:'Cap. 6 · Culpa vs. Vergüenza. El grupo aprende la distinción. Culpa = lo que hice. Vergüenza = quién soy. La culpa es funcional; la vergüenza es corrosiva. Marcus, que empieza a recordar más seguido el incidente de la bici y Aaliyah, escucha con atención.',chart:'CULPA vs. VERGÜENZA (3-5) — columnas emparejadas: «Sobre lo que hice» / «Sobre quién soy» · «Tomé una mala decisión» / «Soy malo» · «Lleva a reparar» / «Lleva a esconderse».',neuro:'Dos tarjetas de pupitre. Amarilla: «Cometí un error. Eso es CULPA. Me dice qué arreglar». Roja: «SOY MALO. Eso es VERGÜENZA. No es cierto. Soy el mismo niño. Cometí un error. Eso es todo». Clasificación literal con código de color.'},
  '3-5|U1·L6 — I Am More Than My Worst Moment': {lesson:'U1·L6 — Soy más que mi peor momento',theme:'Identidad · Integridad tras el fracaso',scene:'Cap. 7 · Soy más que mi peor momento. La clase hace una lista juntos — «Soy la niña que rompió el florero Y la niña que cuida a su prima cada sábado. Y, no PERO».',chart:'SOY MÁS QUE ___ (3-5) — marco de frase con tres espacios: «Soy el niño que ___ Y el niño que ___ Y el niño que ___». Practiquen al unísono.',neuro:'Provea frases de identidad ya generadas que el niño pueda emparejar y reclamar, con un banco de palabras de opciones precisas. Reconocer es más fácil que generar para muchos estudiantes autistas.'},
  '3-5|U2·L1–L2 — The Internal Critic in Real Time': {lesson:'U2·L1–L2 — El Crítico interno en tiempo real',theme:'Autocompasión · El Crítico atrapado en vivo',scene:'Cap. 10 · El peso de la autocrítica. EL COLAPSO DE PRIYA. La escena del proyecto del tigre de Bengala / jaguar. Priya llora en la oficina de la Sra. Calloway: «Soy demasiado. Sigo siendo demasiado». La Sra. Calloway: «Esa voz — ¿eres tú, o es el Crítico interior?». Priya atrapa al Crítico en el acto por primera vez.',chart:'EL CRÍTICO SE PONE RUIDOSO CUANDO… (3-5) — tres detonantes: cuando cometí un error · cuando estoy cansado · cuando tengo miedo. «El Crítico usa tres palabras: SIEMPRE, NUNCA, DEMASIADO».',neuro:'La Tarjeta para Atrapar al Crítico: laminada, en el pupitre. Palabras detonante de un lado (SIEMPRE / NUNCA / DEMASIADO / DEBÍ HABER). Oye una en tu cabeza → voltea la tarjeta: «Ese es el Crítico. No soy yo. Voy a nombrar tres cosas que sí son ciertas». Reconocimiento de patrones por encima de la introspección abstracta.'},
  '3-5|U2·L5 — The Friend Test': {lesson:'U2·L5 — La prueba del amigo',theme:'Autocompasión · Prueba del amigo',scene:'Cap. 13 · Hablarte con amabilidad. Priya, semanas después del colapso, escribe una Carta de Autocompasión: «QUERIDA PRIYA. Si tú fueras Hannah y me dijeras estas cosas, yo diría…». Dibuja a Hannah a la izquierda, a sí misma a la derecha, las mismas palabras amables en ambas burbujas.',chart:'PRUEBA DEL AMIGO (3-5) — izquierda: A MI MEJOR AMIGA (amable, justa, honesta, sin castigo). Derecha: A MÍ MISMA (a menudo dura, a veces cruel). «¿Le dirías eso a tu mejor amiga?».',neuro:'Use un espejo real, o coloque una foto del estudiante donde estaría el amigo. «Estás mirando a una niña que merece lo que le das a Hannah. Esa niña eres tú». El sustituto concreto supera a la autocharla abstracta.'},
  '3-5|U2·L2 — The Weight We Carry (3-5)': {lesson:'U2·L2 — El peso que cargamos (3-5)',theme:'Autocompasión · La mochila pesada (3-5)',scene:'Cap. 10 (rev.) · La mochila regresa. El Sr. Patel saca una versión más pesada de la misma mochila azul de correa rota. El grupo, ya mayor, puede cargar más piedras — pero el encorvarse sigue pasando. Marcus aún no puede soltar la piedra de Aaliyah.',chart:'LA MOCHILA (3-5) — piedras etiquetadas: cosas que hice · cosas que dije · cosas que estoy escondiendo · cosas que otros me hicieron. «Todas las piedras pesan más cuando se cargan en silencio».',neuro:'Provea una Hoja para Clasificar Piedras — tres columnas: MÍAS / NO MÍAS / COMPARTIDAS. Muchos estudiantes cargan piedras que pertenecen a otros sin saber que pueden devolverlas. Clasificar es trabajo de justicia.'},
  '3-5|U2·L6 — I Am More Than My Worst Moment (Application)': {lesson:'U2·L6 — Soy más que mi peor momento (aplicación)',theme:'Autocompasión · El autoperdón más difícil',scene:'Cap. 15 · Cuando perdonarse se siente imposible. Marcus por fin habla de Aaliyah — un sábado por la mañana cuando él tenía ocho años y ella cinco, y dijo algo cruel porque estaba enojado. Ha cargado la piedra por dos años y no sabe cómo soltarla.',chart:'ALGUNAS PIEDRAS TARDAN MÁS (3-5) — una piedra con una línea de tiempo: cargada · examinada · entendida · reparada · soltada. «Seguir cargándola no es fracaso. Es el trabajo en progreso».',neuro:'Protocolo de Liberación Lenta: (1) Nombra la piedra en papel. (2) Identifica la reparación ya hecha. (3) Identifica la reparación pendiente. (4) Si la reparación está completa, la piedra puede soltarse aunque el sentimiento no haya alcanzado. El PROCEDIMIENTO supera al SENTIMIENTO cuando los sentimientos van detrás del comportamiento correcto.'},
  '3-5|U3·L1 — Your Hurt Is Real and It Matters': {lesson:'U3·L1 — Tu dolor es real y importa',theme:'Perdón · Validar el dolor',scene:'Cap. 17 · Tu dolor es real y importa. Maya, que vive con su abuela y no con su madre, expresa — por escrito, no en voz alta — cómo ha sido ser la niña cuya mamá está en otra parte. «Los adultos dicen que no debería sentirme mal por eso. Me siento mal por eso. Ambas cosas pueden ser ciertas».',chart:'EL DOLOR ES REAL AUNQUE… (3-5) — «…no lo hayan hecho a propósito · haya sido hace mucho · otros lo hayan tenido peor». El dolor sigue siendo real.',neuro:'A muchos estudiantes se les ha dicho que su angustia es desproporcionada cuando es proporcionada. «Tu dolor es información, no exageración. Puede ser real y tú puedes seguir adelante. Ambas cosas son ciertas». Nunca enseñe que la magnitud del dolor debe coincidir con la opinión ajena sobre el suceso.'},
  '3-5|U3·L2 — Repair Protocol': {lesson:'U3·L2 — Protocolo de reparación',theme:'Perdón · Protocolo de reparación',scene:'Cap. 19 · Reparación que de verdad funciona. El grupo aprende la diferencia entre la disculpa performativa y la reparación real. «Lo siento SI te lastimé» vs. «Lo siento POR lo que hice. Esto es lo que haré diferente».',chart:'PROTOCOLO DE REPARACIÓN (3-5) — (1) Nombro lo que hice. (2) Nombro el impacto en ti. (3) Nombro lo que haré diferente. «SI» no está en este guion. «PERO» no está en este guion.',neuro:'Distinga la disculpa de REPARACIÓN (tras una acción específica que causó un impacto específico) de la disculpa de APACIGUAMIENTO (autoinculparse crónicamente por existir). Aquí solo se enseña la primera. Interrumpa la segunda — muchos estudiantes autistas han aprendido a disculparse por ser ellos mismos.'},
  '3-5|U3·L3 — Forgiveness vs. Reconciliation': {lesson:'U3·L3 — Perdón vs. Reconciliación',theme:'Perdón · vs. Reconciliación',scene:'Cap. 20 · El perdón no es lo mismo que la confianza. El grupo se sienta con la distinción a nivel 3-5: el perdón es INTERNO; la confianza se GANA. Puedes perdonar y aun así poner un límite. Puedes perdonar y aun así no ser mejores amigos.',chart:'PERDÓN vs. RECONCILIACIÓN (3-5) — dos paneles. Perdón: «Lo que hago dentro de mí». Reconciliación: «Lo que dos personas reconstruyen juntas». El perdón no requiere nada del otro; la reconciliación requiere a AMBOS.',neuro:'Salvaguarda CRÍTICA para estudiantes con mayor riesgo de victimización repetida: «La confianza es un PATRÓN a lo largo del tiempo, no una decisión. Observa el comportamiento. Cambio constante durante muchas semanas → la confianza puede reconstruirse. Sin cambio → la confianza no es tuya para darla y no es tu culpa retenerla».'},
  '3-5|U3·L4 — The Three Sides of Every Story': {lesson:'U3·L4 — Los tres lados de cada historia',theme:'Perdón · Las tres formas',scene:'Cap. 23 · Historias de perdón en la práctica. El grupo escucha tres historias reales a una distancia apropiada para la edad: un hombre que perdonó a un conductor ebrio; una niña que perdonó la mentira de su mejor amiga; una mujer que nunca se reconcilió con el padre que la lastimó — y estuvo en paz de todos modos.',chart:'TRES FORMAS DE PERDÓN (3-5) — (1) Perdón + Reconciliación. (2) Perdón sin Reconciliación. (3) Perdón desde una distancia segura. Las tres son válidas.',neuro:'Establezca de antemano qué forma corresponde a cada situación. Cambió + se disculpó + es seguro → Forma 1 posible. Cambió pero reconstruir no es tu trabajo → Forma 2. NO cambió y es inseguro → Forma 3, sin obligación de involucrarse. Árbol de decisiones, no corazonada.'},
  '3-5|U4·L1 — What Is Grace?': {lesson:'U4·L1 — ¿Qué es la gracia?',theme:'Gracia · Definición',scene:'Cap. 25 · ¿Cómo se ve la gracia? El Sr. Patel presenta la gracia no como un sentimiento sino como una acción elegida — generosidad de espíritu hacia alguien que no se la ganó. La clase comienza la Tarea de Campo de la Brecha de Gracia.',chart:'GRACIA vs. TAPETE (3-5) — GRACIA: una elección · desde la fuerza · protege la dignidad · yo decido qué dar. TAPETE: sin elección · desde el miedo · cede la dignidad · otros toman.',neuro:'Distinción de seguridad crítica. A muchos estudiantes se les ha enseñado a confundir el comportamiento de tapete con amabilidad. Repita la diferencia: «Si no puedes decir que no, no es gracia. Es miedo con una sonrisa».'},
  '3-5|U4·L2 — What Is Mercy?': {lesson:'U4·L2 — ¿Qué es la misericordia?',theme:'Gracia · Misericordia distinta',scene:'Cap. 26 · ¿Cómo se ve la misericordia? Se nombra la misericordia como prima cercana de la gracia — pero distinta. La misericordia es NO dar a alguien lo que merece cuando lo que merece le haría daño. «La misericordia es la elección de perdonar. La gracia es la elección de dar».',chart:'GRACIA vs. MISERICORDIA (3-5) — «LA GRACIA DA lo que no se ganó. LA MISERICORDIA RETIENE lo que se merecía». Dos caras de la misma moneda de generosidad.',neuro:'Ejemplos concretos emparejados. GRACIA: «Le di a Maya la mitad de mi merienda aunque no la pidió». MISERICORDIA: «Devon rompió mi lápiz. Pude habérselo dicho a la maestra. Elegí no hacerlo». Distinga por dirección: la gracia añade, la misericordia retiene.'},
  '3-5|U3·L7 — Limits (carried into U4)': {lesson:'U3·L7 — Límites (llevados a U4)',theme:'Gracia · con límites',scene:'Cap. 27 · Límites desde la fuerza. La Sra. Calloway, en una visita, nombra el Límite. «Un límite es lo que TÚ harás — no lo que le exiges a la otra persona. “Si me gritas, salgo de la habitación” — eso es un límite».',chart:'UN LÍMITE ES (3-5) — «…una declaración sobre lo que yo haré, no una exigencia sobre lo que ellos deben hacer. Desde el respeto propio, no la venganza. Se dice una vez, luego se cumple».',neuro:'Prescriba tres límites que el estudiante pueda ensayar antes de necesitarlos: «Si alguien grita, diré “me voy a apartar” y me iré». «Si alguien toca mi cuerpo sin permiso, digo “no” y le aviso a un adulto». «Si un amigo me pide hacer algo inseguro, digo “no, gracias” y me alejo». Los límites en el cuerpo antes que los límites en la mente.'},
  '3-5|U4·L4–L6 — Micro-Moment Menu / Grace Gap': {lesson:'U4·L4–L6 — Menú de microgestos / Brecha de Gracia',theme:'Gracia · Práctica',scene:'Cap. 30 · Pequeños actos (la Tarea de la Brecha de Gracia). El grupo lleva a casa la Tarea de Campo de la Brecha de Gracia. Cada niño se compromete a tres pequeños actos de gracia durante dos semanas, lleva un diario y comparte sin nombrar a los destinatarios.',chart:'MENÚ DE MICROGESTOS (3-5) — doce pequeños actos en una cuadrícula: «Sonríe al niño que come solo. Agradece al trabajador de la cafetería. Sostén la puerta. Halaga sin esperar nada a cambio. Perdona algo pequeño en silencio…».',neuro:'Imprima de antemano los doce microgestos. Deje que el estudiante ELIJA tres a los que comprometerse — no que genere los suyos. Tres comportamientos concretos con guiones claros superan a un difuso «sé más amable».'},
  '6-8|U1·L1 (expansion) — Identity Audit': {lesson:'U1·L1 (ampliación) — Auditoría de identidad',theme:'Identidad · La máscara específica',scene:'Cap. 2 · La máscara chistosa, ahora en secundaria. Jordan, el niño chistoso del Salón 12 y el Salón 18, encuentra que la Máscara chistosa cuesta más quitársela a medida que sube lo que está en juego socialmente. La risa se vuelve un reflejo de supervivencia.',chart:'AUDITORÍA DE IDENTIDAD (6-8) — dos columnas privadas. Izquierda: quién soy cuando actúo. Derecha: quién soy cuando no. Nunca se recoge. Nunca se comparte.',neuro:'Para estudiantes que usan el humor o la actuación con guion como camuflaje, nómbrelo: «Ser chistoso ES uno de tus seres reales. También es una de tus actuaciones más costosas. Ambas cosas pueden ser ciertas. El agotamiento es información». Permiso para dejar el papel en el salón.'},
  '6-8|U1·L3 — The Digital Backpack': {lesson:'U1·L3 — La mochila digital',theme:'Identidad · El costo digital',scene:'Cap. 3 · La mochila digital. El Instagram de Kezia tiene 312 publicaciones en un feed curado en beige y crema. Su abuela tiene demencia temprana; sus padres están en un divorcio largo. «La Kezia curada y la Kezia real están lo bastante separadas como para que, a la una de la mañana, a Kezia le cueste ubicar cuál de las dos es ella». Marcus aún carga el incidente de la captura de pantalla de junio.',chart:'LA MOCHILA DIGITAL (6-8) — el teléfono es una segunda mochila que carga cada versión curada de ti mismo. Buscable. Permanente. Más pesada que la física. «El internet es un archivo, no un momento».',neuro:'Muchos estudiantes autistas son MÁS vulnerables en lo digital. Prescriba tres reglas: (1) una hora sin teléfono antes de dormir, cargándolo fuera del cuarto. (2) la regla de las 24 horas antes de publicar algo emocional. (3) un adulto de confianza ve las cuentas. No son castigos — son protecciones del sistema nervioso.'},
  '6-8|U2·L1 — The Internal Critic': {lesson:'U2·L1 — El Crítico interno',theme:'Autocompasión · Crítico interno (6-8)',scene:'Cap. 8 · La voz en tu cabeza. El Sr. Patel reintroduce al Crítico interno — más viejo ahora, más sofisticado. El Crítico usa tres tácticas: catastrofizar, generalizar, personalizar. «Es ruidoso, no verdadero».',chart:'CRÍTICO INTERNO · TRES TÁCTICAS (6-8) — Catastrofizar (un mal momento = para siempre). Generalizar (un error = siempre). Personalizar (tiene que ser sobre mí). Más el Testigo Compasivo: la alternativa honesta y justa.',neuro:'Para estudiantes cuyo Crítico se ha amplificado por años de retroalimentación correctiva, el Crítico a menudo habla con la voz de adultos del pasado: «Parte de tu Crítico es tuya. Parte es prestada de personas que intentaron arreglar algo que no necesitaba arreglo. Tienes permiso de cuestionar cuál es cuál».'},
  '6-8|U2·L2 — Highlight Reel vs. Blooper Reel': {lesson:'U2·L2 — Reel de logros vs. Reel de errores',theme:'Autocompasión · Comparación',scene:'Cap. 10 · La trampa de la comparación. El grupo se topa con el Reel de Logros vs. el Reel de Errores — sus propios errores frente a los logros de todos los demás. La comparación está estructuralmente amañada.',chart:'LOGROS vs. ERRORES (6-8) — «La comparación está estructuralmente amañada». Su reel de logros vs. tu reel de errores nunca será una pelea justa. Todos tienen ambos. La mayoría solo muestra uno.',neuro:'Use una metáfora concreta: el tráiler de una película vs. sus escenas eliminadas. «Estás viendo el tráiler de todos los demás y comparándolo con tus propias escenas eliminadas. Esa es la comparación equivocada».'},
  '6-8|U2·L5 — The Friend Test': {lesson:'U2·L5 — La prueba del amigo',theme:'Autocompasión · La prueba del amigo (6-8)',scene:'Cap. 11 · La prueba del amigo. El grupo regresa a la vieja práctica de Priya — escribe lo que le dirías a tu mejor amigo, luego dítelo a ti mismo. Ya mayores, la práctica pesa más.',chart:'PRUEBA DEL AMIGO (6-8) — Izquierda: a mi mejor amigo (amable, justo, honesto, sin castigo). Derecha: a mí mismo (a menudo duro, a veces cruel). «¿Le dirías eso a tu mejor amigo?».',neuro:'Para estudiantes sin un mejor-amigo evidente como referencia: sustituyan por una mascota querida, un hermano menor, un personaje de ficción que amen. El punto es la dirección de la amabilidad. «Lo que le dirías a Hedwig» es una Prueba del Amigo válida.'},
  '6-8|U2·L6 — Rewriting the Script · AFSP safe-messaging guidelines · Counselor co-facilitated': {lesson:'U2·L6 — Reescribir el guion · Según las pautas de mensajes seguros de AFSP · Cofacilitado por consejero/a',theme:'Autocompasión · Autoría narrativa',scene:'Cap. 12 · Reescribir el guion ★★ RIESGO MÁXIMO. El grupo se sienta con el hecho de que, para algunos de ellos, el Crítico ha estado escribiendo el guion de su vida. Aprenden que pueden — despacio, con ayuda — reescribirlo. La ideación suicida está estadísticamente presente en 6-8; aplica el protocolo de Mensajería Segura de la AFSP.',chart:'REESCRIBIR EL GUION (6-8) — el Crítico ha escrito borradores de tu vida desde que eras pequeño. Tienes edad suficiente para empezar a editar. La primera edición es notar que el borrador es editable.',neuro:'Requiere la página de Recursos de Crisis (publicada de forma permanente). El autismo se asocia con mayor riesgo de suicidio; la versión adaptada lo nombra directamente. Informe al consejero/a antes de este capítulo. Provea una vía privada y por escrito para la revelación.'},
  '6-8|U3·L3 — Forgiveness vs. Reconciliation': {lesson:'U3·L3 — Perdón vs. Reconciliación',theme:'Perdón · vs. Reconciliación',scene:'Cap. 15 · Perdón ≠ Confianza ★ RIESGO ALTO. Amara llama a su abuela después de que el comentario de Brielle le llega. Su abuela le da la enseñanza de cuatro partes: Brielle se equivocó; este año eres más tú misma; tú decides qué hacer; tendrás que soltar a Brielle — por ti, no por ella. «Perdón, pero del tipo que no incluye confianza».',chart:'PERDÓN vs. RECONCILIACIÓN (6-8) — dos paneles. Perdón: interno, mío para darlo, no requiere nada del otro. Reconciliación: externo, requiere a AMBOS, cambio de comportamiento a lo largo del tiempo y seguridad.',neuro:'★ SALVAGUARDA DE SEGUIMIENTO DE PATRONES ★ La «interpretación caritativa» sin seguimiento de patrones puede entrenar a los estudiantes a anular una detección de amenaza acertada. «Si esta es la tercera vez que la misma persona ha hecho el mismo tipo de daño — no estás fallando en ser caritativo. Estás RECONOCIENDO UN PATRÓN. Eso es información, no amargura».'},
  '6-8|U3·L6 — The Agency of Release': {lesson:'U3·L6 — La agencia de soltar',theme:'Perdón · La práctica',scene:'Cap. 16 · La carta de liberación ★★ RIESGO MÁXIMO. El Sr. Patel presenta la Carta de Liberación. Cuatro secciones: lo que hiciste; lo que me costó; lo que estoy soltando; lo que me estoy quedando. La carta nunca se envía. «Es un ritual privado que haces para tu propio sistema nervioso».',chart:'CARTA DE LIBERACIÓN (6-8) — cuatro secciones. Nunca se envía. Privada. «Soltar no es lo mismo que estar bien. Soltar no es reconciliación. Soltar no es lo que se ganaron. Soltar es lo que dejas de pagar».',neuro:'★ PROTOCOLO DE VÍA PRIVADA ★ Informe al consejero/a de antemano. Provea una vía por escrito. Para estudiantes sin un destinatario de la carta, permita dibujar en vez de escribir. Permita cartas incompletas. Permita reescribir a lo largo de meses. La herramienta es la práctica, no el objeto.'},
  '6-8|U4·L3 — The Pause': {lesson:'U4·L3 — La pausa',theme:'Gracia · Interpretación caritativa',scene:'Cap. 18 · Interpretación caritativa. El grupo aprende a Pausar antes de decidir qué quiso decir alguien. «Tal vez no vio. Tal vez tuvo una mala mañana. Tal vez no es sobre mí». Tres «tal vez» antes del veredicto.',chart:'LA PAUSA (6-8) — antes de decidir qué significa un comportamiento, enumera tres explicaciones alternativas que no sean sobre ti. Luego decide si tienes suficiente información. «La mayoría de las veces, no la tienes. Aplaza el veredicto».',neuro:'★ SALVAGUARDA DE SEGUIMIENTO DE PATRONES ★ La interpretación caritativa es para situaciones ÚNICAS o AMBIGUAS. Para un daño REPETIDO y que ESCALA no es caritativo anular un reconocimiento de patrones acertado. (1) Primera vez → interpretación caritativa. (2) Segunda → nombra el patrón en privado. (3) Tercera → confía en el patrón. La distancia es sabiduría.'},
  '6-8|U4·L4 — Micro-Moment Menu': {lesson:'U4·L4 — Menú de microgestos',theme:'Gracia · Práctica',scene:'Cap. 19 · Pequeños actos (el Reto de Gracia). El grupo emprende un Reto de Gracia de dos semanas. Tres pequeños actos cada uno. Llevan diarios y comparten sin nombrar a los destinatarios.',chart:'MENÚ DE MICROGESTOS (6-8) — doce actos concretos: «Siéntate con el niño nuevo en el almuerzo una vez. Defiende a un compañero ausente. Agradece por su nombre al trabajador del comedor. Halaga sin esperar nada a cambio. Cubre un pequeño error de un compañero sin decírselo».',neuro:'Imprima de antemano el menú. Deje que el estudiante ELIJA tres. La carga cognitiva de generar actos de gracia es mayor que la de ejecutar los ya escritos. La elección es la libertad; el guion es el andamio.'},
  '6-8|U4·L5 + U3·L7 — Difficult vs. Unsafe / Limits': {lesson:'U4·L5 + U3·L7 — Difícil vs. Inseguro / Límites',theme:'Gracia · con límites',scene:'Cap. 20 · Gracia con personas difíciles. El grupo habla de la gracia hacia personas que no se la han ganado y probablemente nunca lo harán — gracia desde una distancia segura. «La gracia no es lo mismo que el acceso. La gracia puede significar: no estoy pensando cosas crueles de ti, aunque tampoco estés en mi vida».',chart:'DIFÍCIL vs. INSEGURO (6-8) — una persona puede ser DIFÍCIL (molesta, inmadura, agotadora) y aun así recibir gracia. Una persona puede ser INSEGURA (abusiva, peligrosa, depredadora) y la gracia se ve como distancia más el cese del resentimiento. Gracia ≠ acceso.',neuro:'★ CRÍTICO PARA LA SEGURIDAD ★ A muchos estudiantes se les ha manipulado para confundir el comportamiento inseguro con uno meramente difícil. «INSEGURO significa: golpea, amenaza, daña tus cosas, rompe tu confianza repetidamente, te hace sentir inseguro en tu cuerpo. Si ocurre cualquiera de esas cosas, gracia = distancia. No le debes acceso a personas que te han mostrado que son inseguras. NUNCA».'},
  '6-8|U4·L6 — Grace Gap (community application)': {lesson:'U4·L6 — Brecha de Gracia (aplicación comunitaria)',theme:'Gracia · A través del tiempo',scene:'Cap. 21 · Mia vuelve a casa. Mia, que se mudó a Pittsburgh en cuarto grado, regresa para las vacaciones de primavera. El grupo, ahora en séptimo, la recibe distinto que a los nueve años. La gracia como continuación del amor a través de la distancia.',chart:'BRECHA DE GRACIA (6-8) — la brecha entre lo que alguien ha hecho últimamente y lo que aún le extiendes. La brecha es la gracia. «La amistad a través de la distancia se mantiene con lo que decides seguir extendiendo».',neuro:'Para estudiantes cuyas amistades han batallado con la distancia y el tiempo: mantener amistades a distancia es una HABILIDAD, no un rasgo de personalidad. El grupo lo modeló. El grupo lo enseñó. Tú puedes aprenderlo.'},
  '9-10|U2·L1 (9-10) — The Critic in New Rooms': {lesson:'U2·L1 (9-10) — El Crítico en salas nuevas',theme:'Autocompasión · Atrapar al Crítico en solitario',scene:'Cap. 3 · El Crítico interior va a la preparatoria. Priya (en primera persona) atrapa al Crítico dos veces en una clase de geometría. El Crítico es más ruidoso en la sala nueva porque el grupo no está ahí para atraparlo por ella. «El atraparlo, en esta sala, tiene que ser totalmente mío».',chart:'ATRAPAR AL CRÍTICO EN SOLITARIO (9-10) — «El grupo construyó el músculo. La sala de preparatoria es donde el músculo trabaja solo. La práctica era para esto».',neuro:'Provea una Tarjeta para Atrapar al Crítico de tamaño cartera: tres palabras detonante (SIEMPRE, NUNCA, DEMASIADO) y tres contrarrespuestas rápidas — (1) nombra la táctica, (2) di un hecho, (3) respira cuatro tiempos. La tarjeta es el grupo en forma portátil para los momentos en que el grupo no está presente.'},
  '9-10|U1·L1 (9-10) — Mask vs. Mirror': {lesson:'U1·L1 (9-10) — Máscara vs. Espejo',theme:'Identidad · Rechazar la máscara',scene:'Cap. 4 · Amara en el casillero. Amara, en un edificio nuevo con chicos de otras secundarias, se observa casi recaer en la Amara-adyacente. Lo nota y camina a su casillero como Amara-completa. No actúa.',chart:'RECHAZAR LA MÁSCARA (9-10) — «La Máscara se vuelve habitual bajo presión. Puedes rechazarla en los primeros tres días, o pasar cuatro años quitándotela. Recházala temprano».',neuro:'★ EL ENMASCARAMIENTO ES UNA CONDUCTA DE SUPERVIVENCIA DOCUMENTADA ★ La presión por enmascarar alcanza su punto máximo al entrar a la preparatoria. «Puedes hacer stim. Puedes estar callado. Puedes optar por no hacer charla pequeña. Las salas nuevas pueden aprender. No le debes a las salas nuevas un yo curado».'},
  '9-10|U2·L6 (9-10) — When Self-Forgiveness Is Hard': {lesson:'U2·L6 (9-10) — Cuando perdonarse es difícil',theme:'Autocompasión · Cargar lo que aún no se puede soltar',scene:'Cap. 9 · Kezia carga algo. Un familiar distanciado le escribe a la abuela de Kezia. La carta queda sobre el mostrador. Kezia deja de dormir por cuatro semanas, reprueba un examen de biología, le miente a la Sra. Calloway en un correo. La Sra. Calloway la encuentra en el pasillo: «¿Qué está pasando?». Kezia le cuenta todo.',chart:'CARGAR SOLO ES LO MÁS PESADO (9-10) — «En alguna parte de ti, tienes nueve años ahora mismo. La versión antigua de ti que cargaba esto está despierta en tu cuerpo. Eso es normal. Ambas versiones de ti merecen compasión. Ambas necesitan ayuda».',neuro:'★ PARA ESTUDIANTES CON HISTORIAL DE COLAPSO (SHUTDOWN) ★ Cuando algo antiguo resurge, el sistema nervioso autista a menudo regresa a su estado de supervivencia más temprano — colapso, mutismo, regresión en el autocuidado. Esto NO es fracaso; es protección. «Tu cuerpo ya ha hecho esto antes. Sabe cómo esperar a que pase. La espera no tiene que ser en soledad».'},
  '9-10|U2·L2 — The Weight We Carry (Caregiver Strand)': {lesson:'U2·L2 — El peso que cargamos (hilo del cuidador)',theme:'Autocompasión · El cuidador se agota',scene:'Cap. 13 · El Muro en febrero (Theo) ★ CAPÍTULO CLAVE. Febrero. El Muro tiene cien tarjetas. Theo se para frente a él a las 7:42 a. m. durante cuatro minutos y escribe una tarjeta: «He sido el niño que se da cuenta desde primer grado. Este año estoy más cansado de lo que he estado nunca. No sé cómo dejar de darme cuenta». La firma «— T.». La Sra. Calloway la ve a las 8:15. Ella sabe.',chart:'EL NIÑO QUE SE DA CUENTA (9-10) — «El niño que observa la sala es un don. El niño que observa la sala también está en riesgo. Observar solo, por demasiado tiempo, le cuesta al observador más que al observado».',neuro:'★ CUIDADORES AUTISTAS ★ El darse cuenta ES el reconocimiento de patrones autista trabajando horas extra, así que el riesgo de agotamiento es alto. Tres permisos: (1) canaliza lo que notas y deja de rastrearlo. (2) toma un descanso de darte cuenta — un periodo, una semana — fuera de servicio. (3) dile a un adulto: «Estoy lleno. Por favor redirige a quien venga a mí esta semana a otra persona». El rol no es la identidad.'},
  '9-10|U1·L1 / U2·L6 — Identity After the Mask': {lesson:'U1·L1 / U2·L6 — Identidad después de la máscara',theme:'Autocompasión · Identidad tras quitar la máscara',scene:'Cap. 14 · La vieja historia. Jordan, el niño chistoso desde primer grado, se sienta con la Sra. Wong y empieza a trabajar en el guion que el Crítico ha estado escribiendo para él. Jordan: «He sido el chistoso porque ser chistoso me mantenía a salvo. No sé quién soy cuando no estoy siendo chistoso».',chart:'QUIÉN SOY SIN LA MÁSCARA (9-10) — una Red de Identidad en blanco. «No lo sabrás de inmediato. No lo sabrás en una semana. Lo sabrás a lo largo de años. El no-saber es el comienzo del saber».',neuro:'★ ENMASCARAMIENTO Y DESARROLLO DE LA IDENTIDAD ★ Para estudiantes que han enmascarado toda su vida consciente, quitar la Máscara es una excavación lenta, no una decisión. «Puede que no sepas quién eres sin enmascararte. Eso es que el enmascaramiento ha sido muy eficaz. Empieza con una sala. Una preferencia identificable. Un stim que dejas de esconder. Construye desde ahí».'},
  '9-10|U3·L6 (9-10) — The Agency of Release': {lesson:'U3·L6 (9-10) — La agencia de soltar',theme:'Perdón · La carta aplicada',scene:'Cap. 17 · La niña que fue cruel con Priya en cuarto grado. Priya, ahora de catorce, se topa con la niña que fue cruel con ella en cuarto grado — ahora en su clase de química. La niña no se acuerda. Priya recuerda todo. Priya escribe una Carta de Liberación. No la envía. El Crítico se calla por una semana.',chart:'LA CARTA EN LA PRÁCTICA (9-10) — cuatro secciones: lo que hiciste; lo que me costó; lo que estoy soltando; lo que me estoy quedando. «La cuarta sección es la bisagra. Sin “lo que me estoy quedando”, la carta es pérdida. Con ella, la carta es ganancia».',neuro:'Muchos estudiantes autistas cargan daños de hace una década porque la memoria es detallada y el perdón es consciente más que espontáneo. Aquí eso es una ventaja: «Tu memoria guardó esto por años porque fue real. El mismo cerebro que recordó el daño puede escribir la liberación».'},
  '9-10|Grief Strand (cross-cutting U2 and U3)': {lesson:'Hilo de duelo (transversal a U2 y U3)',theme:'Perdón · Duelo sostenido en comunidad',scene:'Cap. 18 · El fin de la temporada. Darius, cuyo perro Pepper ha estado con él desde el kínder, lo acompaña en sus últimas semanas. Pepper muere a finales de primavera. El grupo lo sostiene — Marcus lleva comida, Mia hace videollamada desde Pittsburgh, Maya dibuja a Pepper de memoria.',chart:'DUELO EN COMUNIDAD (9-10) — «El duelo no es un problema por resolver. El duelo es un peso por cargar en compañía. El grupo que aprendió a cargar piedras juntos puede cargar el duelo juntos».',neuro:'★ EL DUELO AUTISTA PUEDE VERSE DISTINTO ★ Puede manifestarse como alteración de la rutina, regresión sensorial, enfoque en un interés especial o aparente apatía — no necesariamente lágrimas o palabras. Ninguna de estas es inapropiada. «No hay una forma correcta de hacer el duelo. Tu forma es tu forma. El grupo se sentará con la que sea tu forma».'},
  '9-10|U4·L1 — Grace as Gift (Generational)': {lesson:'U4·L1 — La gracia como regalo (generacional)',theme:'Gracia · Generacional',scene:'Cap. 19 · El pincel del abuelo. La abuela de Amara le da un pincel que perteneció al abuelo de Amara, quien murió antes de que Amara tuviera edad para recordarlo. «Esto es algo que él hizo. Ahora es algo que tú tienes. La línea pasa por ti».',chart:'GRACIA A TRAVÉS DE LAS GENERACIONES (9-10) — «Lo que se te dio y no ganaste. Lo que le das a la siguiente persona que ella no ganará. La línea de la gracia es lo que hace a una familia, a un grupo, a una comunidad».',neuro:'Para estudiantes cuyas relaciones familiares se han complicado por malentendidos o diferencias sensoriales: «Puedes recibir un regalo de alguien que nunca conociste. Puedes dar un regalo a alguien que aún no existe. La línea no requiere una relación perfecta. La línea solo requiere el regalo».'},
  '9-10|Year-Long Arc — The Sentences That Return': {lesson:'Arco anual — Las frases que regresan',theme:'Las cuatro · La planta de largo plazo',scene:'Cap. 20 · Las frases regresan. Maya, callada desde primer grado, dibuja un sábado tranquilo y se da cuenta de que una frase que la Sra. Calloway leyó en segundo grado le ha vuelto: «Sammy ya sabe que estás aquí. Eso es suficiente por hoy». Maya, a los quince, oye la frase y decide pintar.',chart:'LAS FRASES REGRESAN (9-10) — «Lo que te leyeron a los seis no siempre funciona a los seis. A veces funciona a los quince. A veces a los cuarenta. La lectura no se desperdició. La lectura fue la siembra».',neuro:'★ ESCALAS DE TIEMPO LARGAS ★ Muchos estudiantes autistas absorben el lenguaje de formas que afloran después — a veces años después. «Puede que no hayas mostrado que estabas aprendiendo. Lo estabas. El hecho de que lo uses ahora es la prueba. El maestro que lo sembró no está en la sala. El maestro está en la frase».'},
  '9-10|U4·L7 — Community Charter (high school edition)': {lesson:'U4·L7 — Carta comunitaria (edición preparatoria)',theme:'Las cuatro · Integración portátil',scene:'Cap. 21 · El último día. Termina el primer año de preparatoria. El grupo, disperso todo el año, se reúne en el Salón 104 el último día. La Sra. Calloway: «Han aprendido que el marco funciona aun cuando el grupo no está en la sala. Esa es la prueba del marco. La pasaron».',chart:'EL SALÓN 104 APRENDIÓ (9-10) — «El grupo no es el currículo. El currículo es el regalo que el grupo se hace a sí mismo. Lo cargamos sin los demás en cada sala. De eso se trata todo».',neuro:'Para llevar a casa, portátil: la Tarjeta de Fin de Año ahora superpone las herramientas de cada banda de grado. La misma estructura de tarjeta que el Salón 12, 18, 36, ahora 104. «La misma arquitectura. Salas nuevas».'},
  '11-12|U1·L1 (11-12) — Identity at the Walk-Out': {lesson:'U1·L1 (11-12) — Identidad en la salida',theme:'Identidad · El año umbral',scene:'Cap. 1 · El primer día del último año. La Sra. Calloway, el primer día del último año: «Este es el último año en que los tendré a todos en una sola sala. El año que viene estarán dispersos. Así que este año — seremos honestos. Este año, no fingiremos».',chart:'QUIÉN SOY CUANDO ME VAYA (11-12) — «Lo que me llevo. Lo que dejo. Lo que aún estoy descifrando. Tres columnas. Documento de por vida».',neuro:'★ TRANSICIÓN DE MAYOR RIESGO ★ Haga explícita la arquitectura de la partida: «Necesitarás saber qué te regula, qué dispara el colapso, quiénes son tus contactos de emergencia, cuáles son tus adaptaciones sensoriales, qué dices cuando un compañero de cuarto pregunta por qué haces stim. Escribe cada una de antemano. La versión improvisada de ti en septiembre no es la persona indicada para tomar estas decisiones».'},
  '11-12|U3·L6 (11-12) — The Agency of Release at Adulthood': {lesson:'U3·L6 (11-12) — La agencia de soltar en la adultez',theme:'Perdón · La liberación larga',scene:'Cap. 9 · La carta que Kezia escribió. Kezia, ahora de dieciocho, por fin le escribe de vuelta al familiar que le escribió a su abuela hace tres años. La carta tarda dos meses en redactarse. Tiene un solo párrafo. La envía.',chart:'ALGUNAS LIBERACIONES TARDAN AÑOS (11-12) — «Para lo que no estabas listo a los catorce, puedes estar listo a los dieciocho. O a los veinticinco. O a los cuarenta. La espera no es fracaso. La llegada es el momento correcto».',neuro:'★ HONRAR LAS ESCALAS DE TIEMPO LARGAS ★ Muchos estudiantes autistas procesan decisiones relacionales complejas a lo largo de años, no de semanas. «Tu disposición a tardar tres años en escribir una carta de un párrafo no es postergación. Es tu velocidad de procesamiento para material tan grande. La carta es correcta porque la espera fue correcta».'},
  '11-12|U1·L5 / U3·L1 — Label vs. Integrity': {lesson:'U1·L5 / U3·L1 — Etiqueta vs. Integridad',theme:'Identidad · Integridad bajo presión',scene:'Cap. 10 · La mentira que Marcus casi dijo. A Marcus, en octubre, un oficial de admisiones universitarias le pregunta por una experiencia de liderazgo. Está tentado a exagerar una historia sobre la liga de básquetbol. No lo hace. Cuenta la historia real, más pequeña. Lo aceptan de todos modos.',chart:'INTEGRIDAD BAJO PRESIÓN (11-12) — «Contar la historia verdadera más pequeña en vez de la falsa más grande es, en algún sentido real, todo el currículo de identidad. El ensayo universitario no es el examen. El ensayo universitario es la boleta de calificaciones».',neuro:'Muchos estudiantes autistas batallan con la exageración porque el procesamiento literal la hace cognitivamente incómoda. Replantéelo como fortaleza: «Tal vez te han dicho que eres demasiado literal. En los ensayos universitarios, no redondees hacia arriba. Tu literalidad es tu ventaja».'},
  '11-12|U2·L6 — Rewriting the Script / Real-World': {lesson:'U2·L6 — Reescribir el guion / Mundo real',theme:'Autocompasión · El rechazo no es prueba',scene:'Cap. 12 · La carta (el rechazo universitario de Priya) ★ CAPÍTULO CLAVE. Marzo. Su escuela de primera opción le dice que no. Hannah, su mejor amiga desde cuarto grado, está en la sala. Hannah: «El Crítico puede quedarse con esto por UN día. Mañana empezamos el trabajo de atraparlo en esta. Llevamos diez años atrapándolo. Vamos a atraparlo en esta también».',chart:'EL CRÍTICO Y EL RECHAZO (11-12) — «El Crítico intentará convertir cada rechazo del mundo real en “prueba”. El trabajo es negarse a dejar que un rechazo confirme retroactivamente todo lo que el Crítico ha dicho».',neuro:'Para estudiantes cuyo Crítico ha usado cada rechazo previo como confirmación de una narrativa maestra: «No atraparás al Crítico solo en esta. Le contarás a UNA persona dentro de 24 horas. Esa persona está en tu teléfono ahora mismo. Decide quién es ANTES de que lleguen las decisiones».'},
  '11-12|U3·L3 (11-12) — Forgiveness vs. Reconciliation': {lesson:'U3·L3 (11-12) — Perdón vs. Reconciliación',theme:'Perdón · La conversación adulta',scene:'Cap. 15 · La conversación con mi madre. Maya, de dieciocho, le hace a su madre la pregunta que ha querido hacer desde los seis: «¿Por qué no me criaste?». Su madre — sobria ahora, en terapia — dice la verdad. Maya no la perdona en ese momento. Tampoco la rechaza: «Mamá. Voy a pensar en lo que acabas de decir. Te diré cuando lo haya pensado».',chart:'EL PERDÓN NO REQUIERE UNA FECHA LÍMITE (11-12) — «No tienes que perdonar en el momento, de camino a casa, ni para la próxima Navidad. El perdón es tuyo, en tu tiempo, sin obligación de actuarlo para la persona que te agravió».',neuro:'★ HISTORIAS FAMILIARES QUE INCLUYEN DISTANCIAMIENTO, ADOPCIÓN, CASA HOGAR ★ «Tienes permiso de procesar esto el tiempo que haga falta. Tienes permiso de escribir la respuesta en una carta en vez de decirla. Tienes permiso de nunca cerrar esta pregunta. El perdón, si llega, será real, no performativo. Esa es la única clase que vale la pena dar».'},
  '11-12|U3·L6 (11-12) — The Agency of Release (Real-World)': {lesson:'U3·L6 (11-12) — La agencia de soltar (mundo real)',theme:'Perdón · Liberación parcial',scene:'Cap. 17 · La conversación con mi padre. Marcus tiene una conversación con su padre que ha pospuesto por años. Salen a caminar. Marcus habla. Su padre escucha — por primera vez, solo escucha. No se disculpa ni se defiende. Marcus camina a casa sin haber perdonado a su padre, pero habiendo soltado la mitad de la piedra. La mitad es más de lo que ha soltado jamás.',chart:'LA LIBERACIÓN PARCIAL ES LIBERACIÓN REAL (11-12) — «No tienes que soltar toda la piedra para que cuente como haber hecho el trabajo. La mitad es más que nada. Cualquier liberación es una liberación. El marco de la piedra-entera es el marco del Crítico».',neuro:'Para estudiantes cuyo procesamiento de todo-o-nada ha hecho que el perdón se sienta como una imposibilidad binaria: «La liberación parcial es la forma real de la mayor parte del trabajo de perdón adulto. Puedes soltar la repetición diaria mientras mantienes el límite. Puedes soltar el resentimiento mientras mantienes la cautela. Las categorías son separables».'},
  '11-12|U4·L7 — Community Charter (Closing Ritual)': {lesson:'U4·L7 — Carta comunitaria (ritual de cierre)',theme:'Las cuatro · El grupo como liturgia',scene:'Cap. 20 · La cena del grupo ★ CAPÍTULO CLAVE. Finales de abril. El grupo decide tener una cena juntos — los diez más Hannah más la madre de Mia. Comen en casa de Sofía. Cada persona dice una cosa que se lleva del grupo y una cosa que deja atrás. La cena dura cuatro horas.',chart:'LA CENA DEL GRUPO (11-12) — «Lo que me llevo. Lo que dejo. Dicho en voz alta, frente al grupo. Una vez, en tu vida, este es el ritual».',neuro:'Prescriba de antemano. Provea los dos enunciados con anticipación: «Me llevo ___. Dejo ___». Pueden escribir las respuestas en un diario una semana antes, leerlas en voz alta, pedir que otra persona las lea, o pasar y solo escuchar.'},
  '11-12|U4·L4 — Micro-Moment Menu / Generational': {lesson:'U4·L4 — Menú de microgestos / Generacional',theme:'Gracia · El grupo se reproduce a sí mismo',scene:'Cap. 22 · A Marcus le piden. Marcus le escribe una carta a un estudiante de primer año entrante: «Habrá una persona en tu dormitorio o tu clase que esté sufriendo. Lo verás antes de que diga nada. Querrás arreglarlo. Probablemente no puedas. Pero puedes sentarte a su lado. El sentarse al lado es casi todo. Eso lo aprendí de una maestra llamada Sra. Calloway, de un títere de rana llamado Sammy, y de un muro lleno de tarjetas».',chart:'EL SIGUIENTE GRUPO (11-12) — «Lo que aprendiste se te dio. Lo que das es el siguiente grupo. La arquitectura se reproduce al practicarse, no al preservarse».',neuro:'Muchos estudiantes autistas han pasado su educación siendo receptores de la amabilidad de otros. El último año es el umbral en que se vuelven dadores. «Has recibido mucho. Te has dado cuenta de mucho. Estás por entrar a salas donde puedes construir lo que se construyó para ti».'},
  '11-12|U4·L6 — Grace Gap (Long-Distance)': {lesson:'U4·L6 — Brecha de Gracia (larga distancia)',theme:'Gracia · A través de la distancia, a través del tiempo',scene:'Cap. 23 · Mia regresa. Mia, que se mudó a Pittsburgh en cuarto grado, vuelve para la semana de graduación del grupo. El grupo la recibe — no como la niña que se fue, sino como la niña que volvió. «No dejaste el grupo. El grupo es portátil. El grupo nunca te perdió».',chart:'LA DISTANCIA NO ROMPE AL GRUPO (11-12) — «Los métodos son: contacto regular, regreso intencional, la disposición a ser incomodado. El grupo no se mantiene solo. Al grupo se le mantiene».',neuro:'Para estudiantes a quienes el mantenimiento a larga distancia se les ha dificultado porque las llamadas y la charla pequeña agotan: «Reacciones en el chat grupal. Mensajes de una línea. Notas de voz en vez de llamadas. Visitas una vez al año. Cartas por correo. Hay muchas formas de mantenerlo. No tienes que hacerlo a la manera neurotípica. Tienes que hacerlo. La forma es tuya».'},
  '11-12|Year-End Closing Liturgy': {lesson:'Liturgia de cierre de fin de año',theme:'Las cuatro · La carga final',scene:'Cap. 25 · El discurso. La Sra. Calloway en la graduación: «Están por salir. Han estado construyendo una sala dentro de ustedes durante doce años. La sala está terminada. Es portátil. Llévensela. La van a necesitar. No hoy. No la próxima semana. En la tercera semana de octubre de su primer año de universidad, la van a necesitar. La sala estará ahí».',chart:'LA SALA DENTRO DE TI ES PORTÁTIL (11-12) — «En cualquier edificio en que estés después — la sala que construiste en doce años va contigo. Llegas equipado. El equipo es invisible. También es de carga».',neuro:'Provea una tarjeta final de cartera. Frente: los cuatro pilares. Reverso: las cinco frases ancla (o, en Modo Divino, las cinco Escrituras). «No estarás solo en el dormitorio en octubre. Tendrás esta tarjeta. La tarjeta son doce años de arquitectura. Sigue funcionando».'},
  '11-12|Year-End — Architecture in the Wild': {lesson:'Fin de año — Arquitectura en estado salvaje',theme:'Las cuatro · La arquitectura vivida',scene:'Cap. 26 · La dispersión. El verano entre la preparatoria y la universidad. Sofía le escribe a Mia dos veces por semana. El helado del 14 de agosto de Marcus y Aaliyah. Amara aprende las tres recetas de su abuela. Priya en la biblioteca. Darius y Hope. Jordan escribiendo su libro. Maya pintando para un público. Theo trabajando en una librería, despacio. Kezia en terapia dos veces por semana. Mia en Pittsburgh, empacando.',chart:'EL GRUPO EN ESTADO SALVAJE (11-12) — «La arquitectura, una vez aprendida, no requiere el salón. Funciona en el verano, el dormitorio, el trabajo, el funeral, la boda — y en la tercera semana de octubre cuando no recuerdas por qué viniste a esta escuela».',neuro:'Declaración final que afirma el autismo: «Puede que no te parezcas a los otros estudiantes de primer año en tu nuevo edificio. Está bien. Llegarás con más arquitectura que la mayoría de ellos. La sala dentro de ti tiene la misma forma que la sala que construyó tu grupo. La tarjeta está en tu cartera. No llegas con las manos vacías».'}
});
